#include "mtie/transformer.hpp"
#include <chrono>
#include <iostream>
#include <numeric>
int main(int argc,char** argv){try{std::string text="hello", ids;std::filesystem::path model="demo/demo.mtie",tok="demo/demo.tok";size_t n=12;float temp=0;int topk=0;uint64_t seed=42;for(int i=1;i<argc;++i){std::string a=argv[i];auto val=[&](){if(++i>=argc)throw std::runtime_error("missing value for "+a);return std::string(argv[i]);};if(a=="--text")text=val();else if(a=="--ids")ids=val();else if(a=="--model")model=val();else if(a=="--tokenizer")tok=val();else if(a=="--max-tokens")n=std::stoul(val());else if(a=="--temperature")temp=std::stof(val());else if(a=="--top-k")topk=std::stoi(val());else if(a=="--seed")seed=std::stoull(val());else if(a=="--help"){std::cout<<"mtie_cli [--text TEXT|--ids 1,2] [--model FILE --tokenizer FILE] [--max-tokens N] [--temperature T] [--top-k K] [--seed N]\n";return 0;}else throw std::runtime_error("unknown option: "+a);}auto w=mtie::load_weights(model);auto t=mtie::Tokenizer::load(tok);if(t.tokens.size()!=w.config.vocab_size)throw std::runtime_error("tokenizer vocabulary does not match model");std::vector<uint32_t> p;if(!ids.empty()){size_t pos=0;while(pos<ids.size()){auto end=ids.find(',',pos);p.push_back(std::stoul(ids.substr(pos,end-pos)));if(end==std::string::npos)break;pos=end+1;}}else p=t.encode(text);mtie::Transformer m(std::move(w));auto start=std::chrono::steady_clock::now();(void)m.logits(p);auto prompt_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::vector<double> times;auto out=m.generate(p,n,temp,topk,seed,&times);double avg=times.empty()?0:std::accumulate(times.begin(),times.end(),0.0)/times.size();std::cout<<"tokens: ";for(auto x:out)std::cout<<x<<' ';std::cout<<"\ntext: "<<t.decode(out)<<"\nparameters: "<<m.logits(p).size()<<" logits; model parameters "<<mtie::load_weights(model).parameter_count()<<"\nmodel memory: "<<mtie::load_weights(model).bytes()/1024.0<<" KiB\nprompt processing: "<<prompt_ms<<" ms\naverage generation: "<<avg<<" ms/token\n";}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
